694					// Single-page cursor passthrough: one /repos request, cursor
695					// reported for resumption. The client-side local pipeline
696					// applies to just this page; the cursor survives filtering.
697					return flushThroughPager(cmd, noPager, func() error {
698						return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
699							hostBySlug, err := fetchRepoDirCatalog(ctx, cmd, c)
